import csvtojson from 'csvtojson'

/**
 * Parse CSV text into header names and data rows. All cells remain strings.
 * The first record is the header; blank data records are skipped. Empty or
 * duplicate headers, missing data and inconsistent column counts throw errors.
 *
 * Input:
 *   'id,name\n101,Office\n102,"School, north"'
 * Output:
 *   {
 *     headers: ['id', 'name'],
 *     rows: [['101', 'Office'], ['102', 'School, north']]
 *   }
 */
// shortcut: whole files stay in browser memory; use a worker with chunks if real inputs freeze the UI.
export async function parseCsv(text) {
  // Remove the BOM before parsing so the first header contains only its name.
  const [headers = [], ...dataRows] = await csvtojson({ noheader: true, output: 'csv' }).fromString(
    text.replace(/^\uFEFF/, ''),
  )

  if (!headers.length || headers.some((header) => !header)) {
    throw new Error('CSV must have a non-empty header for every column.')
  }
  if (new Set(headers).size !== headers.length) {
    throw new Error('CSV column names must be unique.')
  }
  const rows = dataRows.filter((row) => row.some((cell) => cell !== ''))
  if (!rows.length) throw new Error('CSV must contain at least one data row.')
  // Each data record must have exactly as many cells as the header.
  rows.forEach((row, index) => {
    if (row.length !== headers.length) {
      throw new Error(`CSV row ${index + 2} has ${row.length} columns; expected ${headers.length}.`)
    }
  })
  return { headers, rows }
}

/**
 * Parse JSON text and check for a non-empty FeatureCollection of Features.
 * Properties must be an object, null, or absent. Geometry is left unchanged.
 * Invalid JSON or an invalid collection/feature structure throws an error.
 *
 * Input:
 *   '{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":101},"geometry":null}]}'
 * Output:
 *   {
 *     type: 'FeatureCollection',
 *     features: [{ type: 'Feature', properties: { id: 101 }, geometry: null }]
 *   }
 */
export function parseGeoJson(text) {
  const collection = JSON.parse(text.replace(/^\uFEFF/, ''))
  if (collection?.type !== 'FeatureCollection' || !Array.isArray(collection.features)) {
    throw new Error('GeoJSON must be a FeatureCollection with a features array.')
  }
  if (!collection.features.length) throw new Error('GeoJSON must contain at least one feature.')
  collection.features.forEach((feature, index) => {
    if (
      feature?.type !== 'Feature' ||
      (feature.properties != null && (typeof feature.properties !== 'object' || Array.isArray(feature.properties)))
    ) {
      throw new Error(`GeoJSON feature ${index + 1} must be a Feature with object or null properties.`)
    }
  })
  return collection
}

/**
 * Convert a string, number or boolean to a trimmed key. Case and leading
 * zeroes are preserved. Empty values and other types cannot match.
 *
 * Examples (input -> output):
 *   ' 101 ' -> '101'
 *   101 -> '101'
 *   0 -> '0'
 *   false -> 'false'
 *   '001' -> '001'
 *   'ABC' -> 'ABC'
 *   '' -> null
 *   null -> null
 *   undefined -> null
 *   [] -> null
 *   {} -> null
 */
export function joinKey(value) {
  return ['string', 'number', 'boolean'].includes(typeof value) ? String(value).trim() || null : null
}
