<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseCsv, parseGeoJson } from './csvGeoJsonMerger.js'
import { prepareShapefile, joinShapefileCsv, writeShapefileZip } from './shapefile.js'
import { downloadFile } from '../shared/download.js'

const collection = shallowRef(null),
  csv = shallowRef(null)
const hasCsv = ref(false),
  column = ref(null),
  property = ref(null)
const loadingGeoJson = ref(false),
  loadingCsv = ref(false),
  exporting = ref(false)
const geoJsonError = ref(''),
  csvError = ref(''),
  error = ref(''),
  result = ref('')
const busy = computed(() => loadingGeoJson.value || loadingCsv.value || exporting.value)
const properties = computed(() =>
  [...new Set(collection.value?.features.flatMap((feature) => Object.keys(feature.properties ?? {})))].sort(),
)
const columns = computed(() => csv.value?.headers.map((title, value) => ({ title, value })) ?? [])
const canExport = computed(
  () => collection.value && (!hasCsv.value || (csv.value && Number.isInteger(column.value) && property.value !== null)),
)

function clearResult() {
  error.value = ''
  result.value = ''
}
async function loadGeoJson(selected) {
  clearResult()
  collection.value = null
  property.value = null
  geoJsonError.value = ''
  const file = Array.isArray(selected) ? selected[0] : selected
  if (!file) return
  loadingGeoJson.value = true
  try {
    collection.value = prepareShapefile(parseGeoJson(await file.text()))
  } catch (failure) {
    geoJsonError.value = `Could not read GeoJSON: ${failure.message}`
  } finally {
    loadingGeoJson.value = false
  }
}
async function loadCsv(selected) {
  clearResult()
  csv.value = null
  column.value = null
  csvError.value = ''
  const file = Array.isArray(selected) ? selected[0] : selected
  hasCsv.value = Boolean(file)
  if (!file) return
  loadingCsv.value = true
  try {
    csv.value = await parseCsv(await file.text())
  } catch (failure) {
    csvError.value = `Could not read CSV: ${failure.message}`
  } finally {
    loadingCsv.value = false
  }
}
async function exportFile() {
  if (!canExport.value || busy.value) return
  clearResult()
  exporting.value = true
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const joined = hasCsv.value ? joinShapefileCsv(csv.value, collection.value, column.value, property.value) : null
    const output = joined?.collection ?? collection.value
    downloadFile(await writeShapefileZip(output, hasCsv.value), 'result.zip', 'application/zip')
    result.value = `${output.features.length} features exported${joined ? `; ${joined.matchedRows} CSV rows matched` : ''}. Downloaded: result.zip.`
  } catch (failure) {
    error.value = `Could not export Shapefile: ${failure.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
const secondFileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form nhận GeoJSON và CSV tùy chọn; khi có CSV mới hiện hai trường đối chiếu, nút xuất tạo bộ shapefile. -->
  <section>
    <h1 class="page-title">GeoJSON → SHP</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportFile">
          <VaFileUpload
            id="geo-shp-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="GeoJSON file"
            file-types=".geojson,.json,application/geo+json"
            :disabled="busy"
            @update:modelValue="loadGeoJson"
          />
          <VaProgressBar v-if="loadingGeoJson" indeterminate aria-label="Reading file" />
          <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
          <VaAlert v-if="geoJsonError" color="danger" role="alert" data-testid="tool-error">{{ geoJsonError }}</VaAlert>
          <p v-if="collection" class="text-sm text-secondary" data-testid="geo-shp-summary">
            {{ collection.features.length }} features
          </p>
          <VaFileUpload
            id="geo-shp-csv"
            v-model="secondFileUpload"
            type="single"
            upload-button-text="CSV file"
            file-types=".csv,text/csv"
            :disabled="busy"
            @update:modelValue="loadCsv"
          />
          <VaProgressBar v-if="loadingCsv" indeterminate aria-label="Reading file" />
          <VaAlert v-if="csvError" color="danger" role="alert" data-testid="tool-error">{{ csvError }}</VaAlert>
          <template v-if="hasCsv">
            <VaSelect
              id="geo-shp-property"
              v-model="property"
              text-by="title"
              value-by="value"
              label="Matching Property Name"
              aria-label="Matching Property Name"
              :options="properties"
              :disabled="busy || !collection"
              @update:modelValue="clearResult"
            />
            <VaSelect
              id="geo-shp-column"
              v-model="column"
              text-by="title"
              value-by="value"
              label="Matching Column"
              aria-label="Matching Column"
              :options="columns"
              :disabled="busy || !csv"
              @update:modelValue="clearResult"
            />
          </template>
          <VaButton type="submit" color="primary" :disabled="!canExport || busy" :loading="exporting"
            >Export SHP</VaButton
          >
        </VaForm>
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
